import{z as n,x as A,o as l,c as p,q as B,j as i,D as t,d as e,s,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"量化误差度量","description":"","frontmatter":{"title":"量化误差度量","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/quant-error-metrics.md","filePath":"llm/quant-error-metrics.md","lastUpdated":1791063341000}'),d={name:"llm/quant-error-metrics.md"};function P(m,a,u,h,f,D){const r=A("Mermaid");return l(),p("div",null,[a[2]||(a[2]=B('<h1 id="量化误差度量" tabindex="-1">量化误差度量 <a class="header-anchor" href="#量化误差度量" aria-label="Permalink to &quot;量化误差度量&quot;">​</a></h1><div class="epigraph"><p>权重 MSE 好看，不等于层输出好看，更不等于聊天还在、算术还在。度量要声明张量对象与任务对象，禁止用一个数结束讨论。</p><footer>—— 对照 SQNR / 层重建误差与困惑度；GPTQ 用 PPL 当苛刻指标</footer></div><p><a href="/llm/fp8-formats">上一课</a>把 E4M3 / E5M2 写成 8-bit 浮点核格式：偏精度对偏范围，必须配缩放，离群照样溢出；它是计算维，不是存储码本维。格子与格式有了。缺口是怎么知道坏了多少：参数域、层输出域、语言模型域、下游任务域，只优化上一层的代理会在下一层翻车。<a href="/llm/gptq">GPTQ</a> 优化 \\(\\|WX-\\hat WX\\|\\) 却用 PPL 签字，已经是跨层。本课把尺子摆齐，不重讲 E4M3 的指数位。后课退化模式默认用这组指标说话。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\|W-\\hat W\\|\\) 对 RTN 友好，对任务不友好（AdaRound 的出发点）。\\(\\|WX-\\hat WX\\|\\) 对齐一层线性，不对齐 softmax 与采样。困惑度对齐下一个 token 的对数损失，对量化敏感，但仍可能掩盖「选择题还对、生成格式已崩」。下游准确率方差大，小掉点看不清。问题是 <strong>同时报一组数，并写明校准域是否等于评测域</strong>。</p><p>SQNR / SNR：信号功率比量化噪声，便于层间比较，单位 dB，不代替任务。饱和率：多少值打在格子端点，诊断 \\(s\\) 是否过小。离群通道占用的码字比例：诊断粒度。</p><p><span class="marginnote">术语翻译：SQNR 就是「信号与量化噪声之比」的对数形式，单位 dB——把量化误差当成录音里的底噪，噪音越小比值越高。它的好处是每层都能算一个、可以横向排序找出最脏的层；坏处是它仍不懂任务，最干净的层不等于对答案最重要的层。</span></p><p><span class="marginnote">评测污染与种子方差是别的课。这里假定评测集干净。量化前后必须同一解码配置，否则温度差会被当成量化差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>推荐最小集：</p><ol><li>逐层重建 MSE / SQNR（校准 \\(X\\) 与一块保留 \\(X\\)）。</li><li>校准域与保留域的 PPL。</li><li>短生成与指令遵循抽样（肉眼或自动格式检查）。</li><li>分能力：算术、代码、长上下文各一。</li></ol><p><span class="marginnote">这套指标像一套体检：逐层 MSE 是体重秤，层输出是血压，困惑度是心电图，下游分能力是让你真跑八百米。体重正常不等于跑得完——PPL 只涨 0.1 的模型，可能已经把长上下文检索这条「腿」跑废了，所以最后一项永远不能省。</span></p><p>若 1 好 2 差：误差在层间累积或校准过拟合。若 2 好 4 差：PPL 不反映该能力，见下一课退化模式。</p>',13)),(l(),i(o,null,{default:t(()=>[s(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%8F%82%E6%95%B0%20MSE%22%5D%20--%3E%20L%5B%22%E5%B1%82%E8%BE%93%E5%87%BA%E9%87%8D%E5%BB%BA%22%5D%0A%20%20L%20--%3E%20PPL%5B%22%E5%9B%B0%E6%83%91%E5%BA%A6%22%5D%0A%20%20PPL%20--%3E%20TASK%5B%22%E5%88%86%E8%83%BD%E5%8A%9B%E4%B8%8B%E6%B8%B8%22%5D%0A%20%20PPL%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%20%2F%20%E6%A0%BC%E5%BC%8F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"比较两种量化器必须锁：校准集、group size、对称性、是否量化头、核路径（真低比特还是解包）。换一项就不是同一工作负载契约——对比方法课的纪律借到这里。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"误差沿残差流相干累积时，逐层 MSE 都「不大」，末端 PPL 已炸。所以只看平均层 MSE 会漏。看末端隐藏态或 logits 的漂移更接近任务。argmax 任务比生成更耐漂移：这是选择题虚稳的机制。",-1)),a[6]||(a[6]=E("p",null,"逐层小误差如何攒成末端大事故：",-1)),(l(),i(o,null,{default:t(()=>[s(r,{id:"mermaid-69",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%AF%8F%E5%B1%82%E7%9A%84%E9%87%8F%E5%8C%96%E8%AF%AF%E5%B7%AE%E7%9C%8B%E8%B5%B7%E6%9D%A5%E9%83%BD%E4%B8%8D%E5%A4%A7%22%5D%20--%3E%20A%5B%22%E8%AF%AF%E5%B7%AE%E6%96%B9%E5%90%91%E7%9B%B8%E5%B9%B2%2C%20%E4%B8%8D%E4%BA%92%E7%9B%B8%E6%8A%B5%E6%B6%88%22%5D%0A%20%20A%20--%3E%20C%5B%22%E6%B2%BF%E6%AE%8B%E5%B7%AE%E6%B5%81%E9%80%90%E5%B1%82%E7%B4%AF%E7%A7%AF%22%5D%0A%20%20C%20--%3E%20H%7B%22%E5%9C%A8%E5%93%AA%E4%B8%80%E5%B1%82%E7%9C%8B%3F%22%7D%0A%20%20H%20--%3E%7C%22%E9%80%90%E5%B1%82%E5%B9%B3%E5%9D%87%20MSE%22%7C%20OK%5B%22%E5%A7%8B%E7%BB%88%E4%B8%8D%E5%A4%A7%20%E2%86%92%20%E8%99%9A%E5%81%87%E5%AE%89%E5%BF%83%22%5D%0A%20%20H%20--%3E%7C%22%E6%9C%AB%E7%AB%AF%20logits%20%E4%B8%8E%20PPL%22%7C%20BAD%5B%22%E6%BC%82%E7%A7%BB%E5%B7%B2%E7%BB%8F%E5%BE%88%E5%A4%A7%2C%20%E4%BB%BB%E5%8A%A1%E5%B7%B2%E5%9D%8F%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=B('<p><span class="marginnote">「相干累积」可以类比走队形：一百个人每人只偏 1 度，若偏的方向各不相同，队伍整体还直；若人人朝同一边偏 1 度，走到第一百步整条队伍已经斜进沟里。量化误差在残差流里就是那种「方向一致」的小偏差，平均数看不出来。</span></p><p>FP8 与 INT 的误差分布形状不同（相对 vs 绝对台阶），同一 MSE 不意味同一 PPL。跨格式比较必须走任务域。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要只报 C4 PPL。不要用训练 CE 当量化验收（那是另一精度路径）。不要把压缩比写进质量表。下一课专门写退化 <strong>模式</strong>：哪些能力先死，以便决定回退 bit 还是改校准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>度量分参数、层输出、PPL、生成、分能力；禁止单点。</li><li>层 MSE 好仍可能末端炸，要看累积与 logits。</li><li>选择题虚稳；生成与长尾先暴露。</li><li>比较量化器必须锁校准与核路径。</li><li>出处：GPTQ 对 PPL 的使用；SQNR / 重建误差工程实践。</li></ul>',6))])}const T=n(d,[["render",P]]);export{C as __pageData,T as default};
